import{z as o,x as i,o as l,c as d,q as A,j as B,D as e,d as t,s,S as r,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"注意力作为内容寻址","description":"","frontmatter":{"title":"注意力作为内容寻址","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/attention-content-address.md","filePath":"llm/attention-content-address.md","lastUpdated":1791063341000}'),p={name:"llm/attention-content-address.md"};function h(m,a,u,D,C,_){const n=i("Mermaid");return l(),d("div",null,[a[2]||(a[2]=A('<h1 id="注意力作为内容寻址" tabindex="-1">注意力作为内容寻址 <a class="header-anchor" href="#注意力作为内容寻址" aria-label="Permalink to &quot;注意力作为内容寻址&quot;">​</a></h1><div class="epigraph"><p>读取不靠「第几个时间步」这根导线，而靠当前查询与各条记忆在内容上有多匹配；地址是算出来的，不是编好的下标。</p><footer>—— 据 Graves, Wayne &amp; Danihelka, Neural Turing Machines；Bahdanau et al., ICLR 2015 整理</footer></div><p><a href="/llm/bahdanau-additive-attention">Bahdanau 加性注意力</a>给出 \\(\\alpha_{tj}\\) 与 \\(c_t\\)。本课不重写 \\(v^\\top\\tanh(\\cdot)\\)。缺口是：要把这件事从「翻译对齐」里抽出来，看成一般的记忆读取接口——查询、记忆槽、按内容的权重、加权读出。没有这次抽象，下一课改打分函数会像换了一层 MLP；有了抽象，点积只是换匹配分数。本课仍不引入缩放、多头、自注意力掩码。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RNN 的读取是时间导线：要拿 \\(t-3\\) 的信息，除非它还留在状态里，否则没有总线。注意力把编码器各步当成一组<strong>可寻址槽</strong>，槽里装着内容 \\(h_j\\)。解码器提供查询 \\(q_t\\)（来自 \\(h_t^{\\mathrm{dec}}\\)）。匹配函数 \\(s(q,h_j)\\) 给出分数，softmax 给出在槽上的分布，读出是期望 \\(\\sum_j\\alpha_j h_j\\)。缺口是承认：地址由内容决定。同一查询下次可以对准不同下标，只要那些槽的内容更像查询。</p><p>这与计算机的按地址读不同：RAM 用整数下标；这里下标是软的、由数据决定的。NTM 把读写头也写成类似接口；本课只借「内容寻址」这个词，不引入外存磁带。</p><p><span class="marginnote">直觉类比：RAM 取货像「去 7 号货架」，门牌号写死在指令里；内容寻址像「去和手里这支样品最像的那堆货」，而且不是只拿一堆，是按相似度给所有货堆分配取货比例——70% 像的、20% 略像的、10% 其余。正因为每一步都在算比例，它才是可微的，梯度才能教模型「该看哪里」。</span></p><h3 id="内容寻址不是键值数据库的精确匹配" tabindex="-1">内容寻址不是键值数据库的精确匹配 <a class="header-anchor" href="#内容寻址不是键值数据库的精确匹配" aria-label="Permalink to &quot;内容寻址不是键值数据库的精确匹配&quot;">​</a></h3><p>槽可以既当「用来匹配的键」又当「用来读出的值」。Bahdanau 里两者都是 \\(h_j\\)。后课可以把键和值分成两次线性投影，那是实现细化：匹配走键，读出走值。本课的抽象允许它们暂时同一。精确匹配（只有完全相等才读出）不可微、也不适合连续向量。softmax 是软匹配：相近的槽都分到质量。不要把注意力理解成哈希表命中。</p><p><span class="marginnote">位置仍可以作为内容的一部分——若 \\(h_j\\) 里混有位置信息。当前尚未把位置单独注入。纯内容寻址对置换不敏感：打乱槽的次序、若内容不变，权重只是跟着槽走，读出集合相同。这正是最后一课「位置还没进模型」的伏笔。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>接口四件套：查询 \\(q\\)，记忆 \\(M=\\{m_j\\}\\)，打分 \\(s(q,m_j)\\)，读出 \\(\\sum_j\\mathrm{softmax}(s)_j\\,m_j\\)（或分开的值 \\(v_j\\)）。Bahdanau 的 \\(s\\) 是加性网络。权重必须在合法槽上归一；掩码仍写在分数上。可以多次读取（多次查询），每次一个 \\(c\\)，不必一次读完所有需要的信息——但本课的 seq2seq 默认每解码步一次。槽的条数等于源长，不是固定记忆库大小。</p>',12)),(l(),B(r,null,{default:e(()=>[s(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%20q%22%5D%20--%3E%20MATCH%5B%22%E5%86%85%E5%AE%B9%E6%89%93%E5%88%86%22%5D%0A%20%20MEM%5B%22%E8%AE%B0%E5%BF%86%E6%A7%BD%22%5D%20--%3E%20MATCH%0A%20%20MATCH%20--%3E%20W%5B%22softmax%20%E5%9C%B0%E5%9D%80%22%5D%0A%20%20MEM%20--%3E%20READ%5B%22%E5%8A%A0%E6%9D%83%E8%AF%BB%E5%87%BA%22%5D%0A%20%20W%20--%3E%20READ%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[t("梯度通过 \\(\\alpha\\) 流入被匹配上的槽，记忆因而被训练成「可被查询的内容」。查询被训练成「提出对的问题」。这是联合学习，没有单独的地址监督。与 LSTM 门的差别：门不选择过去哪一步，只选择当前细胞的哪些维传递；注意力选择"),E("strong",null,"哪一些过去的槽"),t("进入当前步。两者可叠加：编码器仍是 LSTM，读取另走注意力。")],-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"常见误区：初学者容易把注意力当成「查数据库」——查不到就返回空。实际上 softmax 总会把质量分完，哪怕查询和所有槽都不像，读出也不是「没读到」，而是「被迫读了个不相关的平均」。所以模型胡说时，注意力图上照样有看起来很专注的权重分布。")],-1)),a[6]||(a[6]=E("p",null,"多次查询可以读出多个 \\(c\\)，相当于几个读头。seq2seq 默认每解码步一个头。若查询不含足够区分槽的信息，权重会变平，\\(\\alpha\\) 接近均匀，读出退化为平均池化——瓶颈以另一种形式回来。诊断时看 \\(\\alpha\\) 的熵：长期接近 \\(\\log n\\) 说明查询没在寻址。",-1)),a[7]||(a[7]=E("p",null,[E("span",{class:"marginnote"},"数字实例：均匀分布的熵是 \\(\\log n\\)，\\(n=50\\) 个源词时约为 \\(\\ln 50 \\approx 3.9\\)；若某步 \\(\\alpha\\) 几乎全押在一个槽上，熵接近 0。训练中把每步的 \\(\\alpha\\) 熵画成曲线，长期贴着 3.9 不下来的解码步，多半是在平均池化而不是在寻址。")],-1)),a[8]||(a[8]=E("p",null,"计算上，每次查询扫描全部槽，复杂度随记忆长度线性。这是内容寻址的默认代价。稀疏、局部窗口是后话。",-1)),(l(),B(r,null,{default:e(()=>[s(n,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%20q%20%E8%BF%9B%E5%85%A5%E6%89%93%E5%88%86%22%5D%20--%3E%7C%22%E6%90%BA%E5%B8%A6%E8%B6%B3%E5%A4%9F%E5%8C%BA%E5%88%86%E4%BF%A1%E6%81%AF%22%7C%20SHARP%5B%22alpha%20%E9%9B%86%E4%B8%AD%EF%BC%9A%E7%86%B5%E8%BF%9C%E4%BD%8E%E4%BA%8E%20log%20n%22%5D%0A%20%20Q%20--%3E%7C%22%E5%8C%BA%E5%88%86%E4%BF%A1%E6%81%AF%E4%B8%8D%E8%B6%B3%22%7C%20FLAT%5B%22alpha%20%E6%8E%A5%E8%BF%91%E5%9D%87%E5%8C%80%EF%BC%9A%E7%86%B5%E8%B4%B4%E8%BF%91%20log%20n%22%5D%0A%20%20SHARP%20--%3E%20SEL%5B%22%E8%AF%BB%E5%87%BA%E8%BF%91%E4%BC%BC%E9%80%89%E4%B8%AD%E5%B0%91%E6%95%B0%E7%9B%B8%E5%85%B3%E6%A7%BD%22%5D%0A%20%20SEL%20--%3E%20GRAD%5B%22%E6%A2%AF%E5%BA%A6%E9%9B%86%E4%B8%AD%E5%9C%A8%E8%A2%AB%E9%80%89%E6%A7%BD%EF%BC%9A%E8%AE%B0%E5%BF%86%E5%AD%A6%E4%BC%9A%E5%8F%AF%E8%A2%AB%E6%9F%A5%E8%AF%A2%22%5D%0A%20%20FLAT%20--%3E%20AVG%5B%22%E8%AF%BB%E5%87%BA%E7%AD%89%E4%BA%8E%E5%AF%B9%E6%89%80%E6%9C%89%E6%A7%BD%E5%81%9A%E5%B9%B3%E5%9D%87%E6%B1%A0%E5%8C%96%22%5D%0A%20%20AVG%20--%3E%20NOfix%5B%22%E7%9C%8B%E4%BC%BC%E8%AF%BB%E4%BA%86%E3%80%81%E5%AE%9E%E5%88%99%E6%B2%A1%E5%AF%BB%E5%9D%80%EF%BC%9A%E7%93%B6%E9%A2%88%E6%8D%A2%E5%BD%A2%E5%BC%8F%E5%9B%9E%E6%9D%A5%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 \\(s\\) 换成点积，不写 \\(1/\\sqrt{d}\\)。下一课<a href="/llm/additive-to-dot-product">从加性注意力到点积</a>只换匹配函数，不换寻址接口。后课默认：注意力是内容寻址的一次读取；对齐是这一接口在翻译上的特例。硬注意力（对槽做离散抽样）不可用本课的反向规则，不在这里展开。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>内容寻址用查询与槽内容的匹配来生成软地址，再加权读出。</li><li>键与值可以暂时同一；分开投影是后课细化。</li><li>它选择过去哪一些槽，LSTM 门选择当前哪些维传递。</li><li>对槽次序的置换，纯内容读出不变——位置尚未作为独立输入。</li><li>权重过平则退化为平均池化，查询等于没有寻址。</li><li>出处：Bahdanau et al., ICLR 2015；Graves et al., Neural Turing Machines。</li></ul>',4))])}const T=o(p,[["render",h]]);export{f as __pageData,T as default};
